//! Application input: `ApplicationParams` (untrusted, all strings) → `validate()` → `NewApplication` (typed).
//! Generated by `cargo offrails generate model applications request:references{request} pitch:text contact:string`.

use serde::Deserialize;

use super::Model;
use crate::models::Errors;

/// Untrusted input from the application form. This struct IS the permit list: no owner. All strings, so a
/// failed submit re-renders exactly what was typed.
#[derive(Debug, Default, Clone, Deserialize)]
pub struct ApplicationParams {
    #[serde(default)]
    pub request_id: String,
    #[serde(default)]
    pub pitch: String,
    #[serde(default)]
    pub contact: String,
}

/// Validated, typed values. Only `ApplicationParams::validate` makes one.
#[derive(Debug, Clone, PartialEq)]
pub struct NewApplication {
    pub request_id: i64,
    pub pitch: String,
    pub contact: String,
}

impl ApplicationParams {
    /// Rails wording: "can't be blank", "is too long (maximum is N characters)".
    pub fn validate(&self) -> Result<NewApplication, Errors> {
        let mut errors = Errors::default();
        let request_id = match self.request_id.trim() {
            "" => {
                errors.add("request", "must exist");
                0
            }
            raw => match raw.parse::<i64>().ok().filter(|id| *id > 0) {
                Some(v) => v,
                None => {
                    errors.add("request", "must exist");
                    0
                }
            },
        };
        let pitch = self.pitch.trim();
        if pitch.is_empty() {
            errors.add("pitch", "can't be blank");
        } else if pitch.chars().count() > 100000 {
            errors.add("pitch", "is too long (maximum is 100000 characters)");
        }
        let contact = self.contact.trim();
        if contact.is_empty() {
            errors.add("contact", "can't be blank");
        } else if contact.chars().count() > 255 {
            errors.add("contact", "is too long (maximum is 255 characters)");
        }
        errors.into_result(|| NewApplication {
            request_id,
            pitch: pitch.to_owned(),
            contact: contact.to_owned(),
        })
    }
}

/// Prefills the edit form.
impl From<&Model> for ApplicationParams {
    fn from(r: &Model) -> Self {
        Self {
            request_id: r.request_id.to_string(),
            pitch: r.pitch.clone(),
            contact: r.contact.clone(),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn valid() -> ApplicationParams {
        ApplicationParams {
            request_id: "1".into(),
            pitch: "Pitch text".into(),
            contact: "Contact".into(),
        }
    }

    #[test]
    fn valid_params_validate() {
        assert!(valid().validate().is_ok(), "{:?}", valid().validate());
    }

    #[test]
    fn required_fields_cant_be_blank() {
        let errors = ApplicationParams::default().validate().unwrap_err();
        assert_eq!(errors.on("request"), ["must exist"]);
        assert_eq!(errors.on("pitch"), ["can't be blank"]);
        assert_eq!(errors.on("contact"), ["can't be blank"]);
    }

    #[test]
    fn strings_have_a_maximum_length() {
        let at_max = ApplicationParams {
            pitch: "x".repeat(100000),
            ..valid()
        };
        assert!(at_max.validate().is_ok());
        let over = ApplicationParams {
            pitch: "x".repeat(100001),
            ..valid()
        };
        assert_eq!(
            over.validate().unwrap_err().on("pitch"),
            ["is too long (maximum is 100000 characters)"]
        );
        let at_max = ApplicationParams {
            contact: "x".repeat(255),
            ..valid()
        };
        assert!(at_max.validate().is_ok());
        let over = ApplicationParams {
            contact: "x".repeat(256),
            ..valid()
        };
        assert_eq!(
            over.validate().unwrap_err().on("contact"),
            ["is too long (maximum is 255 characters)"]
        );
    }

    #[test]
    fn typed_fields_reject_garbage() {
        let bad = ApplicationParams {
            request_id: "abc".into(),
            ..valid()
        };
        assert_eq!(bad.validate().unwrap_err().on("request"), ["must exist"]);
    }
}
